const hxCss=`:root{--blue1:#5DABFE;--blue2:#3391FF;--blue3:#2E7EDB;--ring:#50A2FE;--bg:#f4f5f7;--surface:#fff;--surface2:#eef0f3;--border:#e4eaf0;--text:#1A202C;--muted:#8a93a6;--radius:14px;--shadow:0 1px 2px rgba(16,24,40,.05),0 10px 28px rgba(16,24,40,.07)}[data-theme=dark]{--bg:#181b1d;--surface:#262A2D;--surface2:#31363a;--border:#394146;--text:#fff;--muted:#B3BAC6;--shadow:0 1px 2px rgba(0,0,0,.4),0 12px 30px rgba(0,0,0,.42)}*{box-sizing:border-box}html,body{margin:0;padding:0}body{background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif,'Apple Color Emoji','Segoe UI Emoji';-webkit-font-smoothing:antialiased;background-image:radial-gradient(620px 300px at 12% -6%,rgba(80,162,254,.10),transparent),radial-gradient(700px 340px at 92% -4%,rgba(51,145,255,.08),transparent);background-repeat:no-repeat}.wrap{max-width:1060px;margin:0 auto;padding:30px 24px 80px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:26px}.brand{display:flex;align-items:center;gap:9px;font-size:13px;font-weight:700;color:var(--muted)}.dot{width:20px;height:20px;border-radius:6px;background:linear-gradient(145deg,var(--blue1),var(--blue2));box-shadow:0 6px 12px -6px rgba(49,144,255,.65)}.btn{height:36px;padding:0 15px;border-radius:9px;border:1px solid var(--border);background:var(--surface);color:var(--text);font:inherit;font-size:13px;font-weight:600;cursor:pointer;box-shadow:var(--shadow);display:inline-flex;align-items:center;gap:7px;transition:all .12s;user-select:none}.btn:hover{transform:translateY(-1px);filter:brightness(1.03)}.hero{position:relative;overflow:hidden;display:flex;align-items:center;gap:20px;padding:30px 32px;background:linear-gradient(160deg,var(--surface),var(--surface2));border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow)}.hero:after{content:'';position:absolute;right:-70px;top:-90px;width:240px;height:240px;border-radius:50%;background:radial-gradient(circle,rgba(80,162,254,.20),transparent 70%);pointer-events:none}.wemoji{font-size:52px;line-height:1;flex:0 0 auto;filter:drop-shadow(0 6px 14px rgba(49,144,255,.25))}.wemoji img{width:54px;height:54px;border-radius:9px;object-fit:cover;box-shadow:var(--shadow)}.htitle{margin:0;font-size:26px;font-weight:800;letter-spacing:-.2px}.hsub{margin:7px 0 0;display:flex;gap:9px;align-items:center;flex-wrap:wrap;font-size:12.5px;color:var(--muted)}.chip{background:rgba(80,162,254,.13);color:var(--blue2);border-radius:999px;padding:3px 11px;font-size:12px;font-weight:700}.date{font-size:12px;color:var(--muted)}.toolbar{display:flex;gap:12px;align-items:center;margin:24px 0 18px}.search{flex:1;display:flex;align-items:center;gap:10px;background:var(--surface);border:1px solid var(--border);border-radius:11px;padding:11px 15px;box-shadow:var(--shadow);min-width:0}.search svg{flex:0 0 auto}.search input{flex:1;min-width:0;border:none;outline:none;background:transparent;font:inherit;font-size:14px;color:var(--text)}.search input::placeholder{color:var(--muted)}.cnt{font-size:12px;color:var(--muted);white-space:nowrap}.cat{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow);margin-bottom:18px;overflow:hidden}.cat.hide{display:none}.cat-head{display:flex;align-items:center;gap:11px;padding:15px 20px;border-bottom:1px solid var(--border);background:var(--surface2)}.cat-head .ico{font-size:21px;line-height:1}.cat-head h2{margin:0;font-size:15.5px;font-weight:700;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cat-head .n{font-size:11.5px;color:var(--muted);font-weight:600}.tab{display:flex;align-items:center;gap:13px;padding:11px 20px;cursor:pointer;transition:background .1s}.tab+.tab{border-top:1px solid var(--border)}.tab:hover{background:var(--surface2)}.fav{width:26px;height:26px;flex:0 0 26px;border-radius:7px;display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:13px;font-weight:800;color:#fff;background:linear-gradient(145deg,var(--blue1),var(--blue2));box-shadow:0 4px 8px -4px rgba(49,144,255,.5)}.fav img{width:26px;height:26px}.tt{flex:1;min-width:0}.ti{font-size:14px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.th{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px}.copy{opacity:0;background:transparent;border:1px solid var(--border);color:var(--muted);border-radius:8px;height:30px;width:30px;min-width:30px;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .12s;font:inherit;font-size:13px}.tab:hover .copy{opacity:1}.copy:hover{color:#fff;background:linear-gradient(145deg,var(--blue1),var(--blue2));border-color:transparent;box-shadow:0 8px 14px -6px rgba(49,144,255,.55)}.empty{padding:52px 20px;text-align:center;color:var(--muted);font-size:14px;display:none}.empty.show{display:block}.foot{margin-top:34px;padding-top:20px;border-top:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;color:var(--muted);font-size:12px}.g{font-weight:800;background:linear-gradient(90deg,var(--blue1),var(--blue2));-webkit-background-clip:text;background-clip:text;color:transparent}.toast{position:fixed;left:50%;bottom:26px;transform:translateX(-50%) translateY(90px);background:#262A2D;color:#fff;border-radius:10px;padding:11px 18px;font-size:13px;font-weight:600;box-shadow:0 12px 30px rgba(0,0,0,.35);transition:transform .25s cubic-bezier(.2,.8,.2,1);opacity:0;pointer-events:none;z-index:60;max-width:90vw}.toast.show{transform:translateX(-50%) translateY(0);opacity:1}@media (max-width:640px){.tab{padding:11px 14px}.cat-head{padding:13px 14px}.hero{padding:22px 18px}.htitle{font-size:21px}.wemoji{font-size:40px}}`;
